#!/bin/bash
# Task 090 -- meshsim cc-cores verification (WORKER14): branch cc-cores (5cd78a2), C&C 1-3 as real cores behind
# Config.ccCores (off by default), merged with main 8224b97.
#  1. run_tests.sh's quick suite (every "$J" step outside full mode), 8 at a time (tools/run_quick.sh): every existing
#     suite with the switch off, plus CcCoresTest (the switch on: the controllers' boot, phases, the error path);
#  2. its full-mode extras, 4 at a time (tools/run_full.sh), with CcBench (the boot and a phase, cores against the model).
# The kit (cc-cores/meshsim built at Java 17 with every image prebuilt, including sw/cc's; cc-cores/sw, tables,
# tools/replayer-opcodes) is embedded below, SHA-256 checked; smoke-tested locally (run_quick on bus, regdoc, replayer,
# reqbus, riscv, stageb, cccores, hooks, periph, cond; CcBench). Expected ~15 min.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/090-w14-cc-cores-verify; mkdir -p "$RES"
WANT=d51bfc894234631f5a3c74f560267a64cb2a749ecad92330c0a8086cb947be1e
W=/tmp/w14-090; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
cd "$W/cc-cores/meshsim" || exit 2
P=8 bash tools/run_quick.sh "$W/out"; RQ=$?
P=4 bash tools/run_full.sh "$W/out"; RF=$?
echo "run_quick.sh exit $RQ, run_full.sh exit $RF at $(date -u)"
cp "$W"/out/* "$RES/" 2>/dev/null
cat "$W/out/VERDICT.txt" "$W/out/FULL-VERDICT.txt" 2>/dev/null
echo "--- CcBench"; cat "$W/out/ccbench.log" 2>/dev/null
rm -rf "$W"
[ $RQ = 0 ] && [ $RF = 0 ]; exit $?
